def _age_str(iso_date: str) -> str:
    """Convert ISO datetime to human-readable age in days."""
    try:
        created = datetime.fromisoformat(iso_date.replace("Z", "+00:00"))
        days = (datetime.now(timezone.utc) - created).days
        return f"{days}d" if days > 0 else "<1d"
    except (ValueError, TypeError):
        return ""


def _repo_from_url(repository_url: str) -> str:
    """Extract 'owner/repo' from GitHub API repository_url."""
    # https://api.github.com/repos/owner/repo -> owner/repo
    parts = repository_url.rstrip("/").split("/")
    if len(parts) >= 2:
        return f"{parts[-2]}/{parts[-1]}"
    return repository_url


def _fetch_prs(query: str) -> list[dict[str, Any]]:
    """Run gh api search and return items list."""
    result = run_cmd(
        [
            "gh",
            "api",
            "--paginate",
            f"/search/issues?q={query}&per_page=100",
        ],
        timeout=120,
    )
    if result.returncode != 0:
        logger.warning("gh api failed: %s", result.stderr[:200])
        return []
    # --paginate concatenates JSON objects; parse each one
    all_items: list[dict[str, Any]] = []
    for line in result.stdout.splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            all_items.extend(json.loads(line).get("items", []))
        except json.JSONDecodeError:
            continue
    return all_items


_DECISION_STATES = {"APPROVED", "CHANGES_REQUESTED"}


def _fetch_review_meta(
    prs: list[dict[str, Any]],
) -> dict[str, tuple[int, bool]]:
    """Per-PR review metadata for current user.

    Returns {url: (cr_count, active_cr)} where cr_count is how many times
    the user submitted CHANGES_REQUESTED, and active_cr is whether the
    user's latest decision is CHANGES_REQUESTED.
    """
    user_result = run_cmd(["gh", "api", "user"], timeout=30)
    if user_result.returncode != 0:
        return {}
    try:
        login = json.loads(user_result.stdout).get("login", "")
    except json.JSONDecodeError:
        return {}
    if not login:
        return {}

    meta: dict[str, tuple[int, bool]] = {}
    for pr in prs:
        url = pr.get("html_url", "")
        repo = _repo_from_url(pr.get("repository_url", ""))
        number = pr.get("number", "")
        if not repo or not number:
            meta[url] = (0, False)
            continue
        result = run_cmd(
            ["gh", "api", "--paginate", f"/repos/{repo}/pulls/{number}/reviews"],
            timeout=30,
        )
        if result.returncode != 0:
            meta[url] = (0, False)
            continue
        try:
            reviews = json.loads(result.stdout)
        except json.JSONDecodeError:
            # --paginate may concatenate JSON arrays
            reviews = []
            for line in result.stdout.splitlines():
                line = line.strip()
                if line:
                    try:
                        chunk = json.loads(line)
                        if isinstance(chunk, list):
                            reviews.extend(chunk)
                    except json.JSONDecodeError:
                        continue
        my_reviews = [r for r in reviews if r.get("user", {}).get("login") == login]
        cr_count = sum(1 for r in my_reviews if r.get("state") == "CHANGES_REQUESTED")
        active_cr = False
        for r in reversed(my_reviews):
            if r.get("state") in _DECISION_STATES:
                active_cr = r["state"] == "CHANGES_REQUESTED"
                break
        meta[url] = (cr_count, active_cr)
    return meta


def _fetch_incoming_change_requests(
    prs: list[dict[str, Any]],
) -> dict[str, int]:
    """For authored PRs, count reviewers whose latest decision is CHANGES_REQUESTED."""
    counts: dict[str, int] = {}
    for pr in prs:
        url = pr.get("html_url", "")
        repo = _repo_from_url(pr.get("repository_url", ""))
        number = pr.get("number", "")
        if not repo or not number:
            continue
        result = run_cmd(
            ["gh", "api", "--paginate", f"/repos/{repo}/pulls/{number}/reviews"],
            timeout=30,
        )
        if result.returncode != 0:
            continue
        try:
            reviews = json.loads(result.stdout)
        except json.JSONDecodeError:
            reviews = []
            for line in result.stdout.splitlines():
                line = line.strip()
                if line:
                    try:
                        chunk = json.loads(line)
                        if isinstance(chunk, list):
                            reviews.extend(chunk)
                    except json.JSONDecodeError:
                        continue
        # Group by reviewer, find latest decision per reviewer
        by_reviewer: dict[str, str] = {}
        for r in reviews:
            login = r.get("user", {}).get("login", "")
            state = r.get("state", "")
            if login and state in _DECISION_STATES:
                by_reviewer[login] = state
        cr_count = sum(1 for s in by_reviewer.values() if s == "CHANGES_REQUESTED")
        counts[url] = cr_count
    return counts


def _fetch_pr_details(
    prs: list[dict[str, Any]],
) -> tuple[set[str], dict[str, tuple[int, int]]]:
    """Merge-queue membership and diff size per PR.

    Returns (queued_urls, {url: (additions, deletions)}).

    One GraphQL query per repo using aliases to batch PR lookups.
    Avoids paginating all open PRs — queries only the PRs we have.
    """
    # Group by repo
    by_repo: dict[str, list[dict[str, Any]]] = {}
    for pr in prs:
        repo = _repo_from_url(pr.get("repository_url", ""))
        if repo:
            by_repo.setdefault(repo, []).append(pr)

    queued: set[str] = set()
    diffstat: dict[str, tuple[int, int]] = {}
    for repo, repo_prs in by_repo.items():
        parts = repo.split("/")
        if len(parts) != 2:
            continue
        owner, name = parts
        # Build aliased query for each PR in this repo
        fragments = []
        for i, pr in enumerate(repo_prs):
            n = pr.get("number", 0)
            if not n:
                continue
            fragments.append(
                "pr%d: pullRequest(number: %d)"
                " { number additions deletions mergeQueueEntry"
                " { position } }" % (i, n)
            )
        if not fragments:
            continue
        body = " ".join(fragments)
        query = '{ repository(owner: "%s", name: "%s")' " { %s } }" % (
            owner,
            name,
            body,
        )
        result = run_cmd(
            ["gh", "api", "graphql", "-f", f"query={query}"],
            timeout=30,
        )
        if result.returncode != 0:
            continue
        try:
            data = json.loads(result.stdout)
            repo_data = data.get("data", {}).get("repository", {})
            for i, pr in enumerate(repo_prs):
                node = repo_data.get(f"pr{i}")
                url = pr.get("html_url", "")
                if not node or not url:
                    continue
                if node.get("mergeQueueEntry"):
                    queued.add(url)
                if node.get("additions") is not None:
                    diffstat[url] = (
                        node.get("additions", 0),
                        node.get("deletions", 0),
                    )
        except (json.JSONDecodeError, AttributeError):
            continue
    return queued, diffstat


def _label_starred_urls(
    prs: list[dict[str, Any]],
    starred_labels: set[str],
) -> set[str]:
    """URLs of PRs carrying at least one starred label."""
    if not starred_labels:
        return set()
    return {
        p["html_url"]
        for p in prs
        if p.get("html_url")
        and starred_labels & {lbl.get("name", "") for lbl in p.get("labels", [])}
    }


