    def refresh(self, *, show_status: bool = True) -> None:
        if self._refreshing:
            self._skipped_refreshes += 1
            tag = "error" if self._skipped_refreshes > 6 else "warning"
            n = self._skipped_refreshes
            self._log(
                f"PRs tab: refresh skipped ({n}x)," " previous still running",
                tag,
            )
            return
        self._refreshing = True
        self._refresh_btn.configure(fg=COLOR_PROGRESS)
        if show_status:
            self._status_var.set("Refreshing...")
        thread = threading.Thread(target=self._do_refresh, daemon=True)
        thread.start()

    def _schedule_auto_refresh(self, delay_ms: int | None = None) -> None:
        def _tick() -> None:
            self.refresh(show_status=False)
            self._schedule_auto_refresh()

        self._auto_refresh_id = self._root.after(
            self._auto_refresh_ms if delay_ms is None else delay_ms,
            _tick,
        )

    def _do_refresh(self) -> None:
        try:
            # review-requested:@me misses PRs after submitting a review
            # (GitHub removes user from requested reviewers). Query both
            # and merge to get the full reviewer universe.
            requested = _fetch_prs(
                "is:pr+review-requested:@me+state:open+archived:false"
            )
            requested_urls = {p.get("html_url", "") for p in requested}
            reviewed = _fetch_prs(
                "is:pr+reviewed-by:@me+state:open+archived:false+-author:@me"
            )
            seen = set(requested_urls)
            for p in reviewed:
                url = p.get("html_url", "")
                if url not in seen:
                    requested.append(p)
                    seen.add(url)
            review = requested
            my = _fetch_prs(
                "is:pr+author:@me+state:open+archived:false+sort:updated-desc"
            )
            review_meta = _fetch_review_meta(review)
            incoming_cr = _fetch_incoming_change_requests(my)
            all_prs = review + my
            queued, diffstat = _fetch_pr_details(all_prs)
            self._save_cache(
                review,
                my,
                review_meta,
                queued,
                incoming_cr,
                requested_urls,
                diffstat,
            )
            self._schedule(
                self._on_data_loaded,
                review,
                my,
                review_meta,
                queued,
                incoming_cr,
                requested_urls,
                diffstat,
            )
        except Exception:
            logger.exception("PR refresh failed")
            self._refreshing = False
            self._schedule(self._refresh_btn.configure, {"fg": FG_TEXT})
            self._schedule(
                self._log, "PRs tab: refresh failed, see logs for details", "error"
            )

    def _log(
        self,
        message: str,
        tag: str = "info",
        link: str = "",
        link_label: str = "",
    ) -> None:
        if self._console_log:
            self._console_log(message, tag, link, link_label)
        else:
            logger.warning(message)

    def _on_data_loaded(
        self,
        review_prs: list[dict[str, Any]],
        my_prs: list[dict[str, Any]],
        review_meta: dict[str, tuple[int, bool]],
        queued_urls: set[str],
        incoming_cr_counts: dict[str, int],
        requested_urls: set[str],
        diffstat: dict[str, tuple[int, int]],
    ) -> None:
        self._refreshing = False
        self._refresh_btn.configure(fg=FG_TEXT)
        self._skipped_refreshes = 0
        old_urls = self._requested_urls
        new_review_requests = requested_urls - old_urls
        self._review_prs = review_prs
        self._my_prs = my_prs
        self._review_meta = review_meta
        self._queued_urls = queued_urls
        self._incoming_cr_counts = incoming_cr_counts
        self._requested_urls = requested_urls
        self._diffstat = diffstat
        self._update_label_list()
        self._apply_label_stars()
        self._render()
        if old_urls and new_review_requests:
            if self._notify_tab:
                self._notify_tab("PR")
            new_prs = [
                p for p in review_prs if p.get("html_url", "") in new_review_requests
            ]
            for p in new_prs:
                url = p.get("html_url", "")
                title = p.get("title", "")
                repo = _repo_from_url(p.get("repository_url", ""))
                self._log(
                    f"[PRs] new review request:" f" {repo} — {title}",
                    "warning",
                    link=url,
                )

    def _render(self) -> None:
        self._text.configure(state=tk.NORMAL)
        self._text.delete("1.0", tk.END)
        self._row_widgets.clear()
        self._compute_columns()

        self._render_section("Review Requested", self._review_prs, is_review=True)
        self._render_section("My PRs", self._my_prs)

        self._text.configure(state=tk.DISABLED)
        self._update_status()

    def _compute_columns(self) -> None:
        """Widest value per numeric column, so rows line up."""
        all_prs = self._review_prs + self._my_prs
        counts = [len(f"({m[0]})") for m in self._review_meta.values()]
        counts += [len(f"({n})") for n in self._incoming_cr_counts.values()]
        self._col_count = max(counts, default=0)
        self._col_comments = max(
            (len(f"[{p.get('comments', 0)}]") for p in all_prs), default=0
        )
        self._col_add = max(
            (len(f"+{a}") for a, _ in self._diffstat.values()), default=0
        )
        self._col_del = max(
            (len(f"-{d}") for _, d in self._diffstat.values()), default=0
        )

    def _update_label_list(self) -> None:
        all_prs = self._review_prs + self._my_prs
        labels = sorted(
            {
                lbl.get("name", "")
                for p in all_prs
                for lbl in p.get("labels", [])
                if lbl.get("name")
            }
        )
        current = self._label_filter_var.get()
        self._label_combo["values"] = ["All"] + labels
        if current != "All" and current not in labels:
            self._label_filter_var.set("All")
        self._update_label_star_btn()

    def _is_active_cr(self, url: str) -> bool:
        meta = self._review_meta.get(url)
        return meta[1] if meta else False

    def _update_status(self) -> None:
        all_prs = self._review_prs + self._my_prs
        draft_count = sum(1 for p in all_prs if p.get("draft", False))
        queued_count = sum(
            1 for p in all_prs if p.get("html_url", "") in self._queued_urls
        )
        dismissed_count = sum(
            1 for p in all_prs if p.get("html_url", "") in self._dismissed
        )
        cr_count = sum(1 for p in all_prs if self._is_active_cr(p.get("html_url", "")))
        self._filter_buttons["Drafts"][3].set(f"Drafts:{draft_count}")
        self._filter_buttons["Queued"][3].set(f"Queued:{queued_count}")
        self._filter_buttons["Chg Req"][3].set(f"Chg Req:{cr_count}")
        self._filter_buttons["Dismissed"][3].set(f"Dismissed:{dismissed_count}")
        review_actionable = sum(
            1
            for p in self._review_prs
            if p.get("html_url", "") in self._requested_urls
            and p.get("html_url", "") not in self._dismissed
            and not p.get("draft", False)
            and p.get("html_url", "") not in self._queued_urls
        )
        self._status_var.set(f"{review_actionable} actionable")

        if self._notebook is not None:
            tab_text = f"PR:{review_actionable}"
            try:
                self._notebook.tab(self._parent, text=tab_text)
            except tk.TclError:
                pass

    def _render_section(
        self,
        title: str,
        prs: list[dict[str, Any]],
        *,
        is_review: bool = False,
    ) -> None:
        show_drafts = self._show_drafts_var.get()
        show_queued = self._show_queued_var.get()
        show_dismissed = self._show_dismissed_var.get()
        show_cr = self._show_changes_requested_var.get()
        # Mutually exclusive: if a filter is active, show ONLY that
        exclusive = show_drafts or show_queued or show_dismissed or show_cr

        def _include(p: dict[str, Any]) -> bool:
            url = p.get("html_url", "")
            is_draft = bool(p.get("draft", False))
            is_queued = url in self._queued_urls
            is_dismissed = url in self._dismissed
            is_cr = self._is_active_cr(url)
            if exclusive:
                if show_drafts:
                    return is_draft
                if show_queued:
                    return is_queued
                if show_cr:
                    return is_cr
                if show_dismissed:
                    return is_dismissed
            if is_review:
                return (
                    url in self._requested_urls
                    and not is_draft
                    and not is_queued
                    and not is_dismissed
                )
            # My PRs: hide drafts, queued, dismissed
            return not is_draft and not is_queued and not is_dismissed

        visible = [p for p in prs if _include(p)]
        label_filter = self._label_filter_var.get()
        if label_filter != "All":
            visible = [
                p
                for p in visible
                if any(lbl.get("name") == label_filter for lbl in p.get("labels", []))
            ]
        active_count = sum(
            1 for p in visible if p.get("html_url", "") not in self._dismissed
        )

        self._text.insert(tk.END, f"{title} ({active_count})\n", "section")

        if not visible:
            self._text.insert(tk.END, "  None\n\n", "dim")
            return

        visible.sort(
            key=lambda p: p.get("created_at", ""),
            reverse=self._newest_first,
        )
        visible.sort(key=lambda p: _repo_from_url(p.get("repository_url", "")))
        # Priority PRs float to top
        visible.sort(
            key=lambda p: p.get("html_url", "") not in self._priority,
        )
        last_repo = ""
        for pr in visible:
            repo = _repo_from_url(pr.get("repository_url", ""))
            if last_repo and repo != last_repo:
                self._text.insert(
                    tk.END,
                    "─" * 120 + "\n",
                    "separator",
                )
            last_repo = repo
            self._render_pr_row(pr)
        self._text.insert(tk.END, "\n")

    def _render_pr_row(self, pr: dict[str, Any]) -> None:
        url = pr.get("html_url", "")
        number = pr.get("number", "")
        title = pr.get("title", "")
        repo = _repo_from_url(pr.get("repository_url", ""))
        age = _age_str(pr.get("created_at", ""))
        draft = pr.get("draft", False)
        is_queued = url in self._queued_urls
        is_dismissed = url in self._dismissed
        is_priority = url in self._priority

        self._text.insert(tk.END, f"{age:>4} ", "age")

        # Priority star toggle
        def _make_toggle_priority(u: str = url) -> None:
            self._toggle_priority(u)

        star_btn = tk.Button(
            self._text,
            text="★" if is_priority else "☆",
            command=_make_toggle_priority,
            width=2,
            bg=BG_OUTPUT,
            fg=COLOR_NOTIFICATION_BELL if is_priority else FG_DIM,
            font=self._font_body,
            relief=tk.FLAT,
            activebackground=COLOR_BUTTON_ACTIVE,
            cursor="hand2",
            padx=1,
            pady=0,
            borderwidth=0,
        )
        self._text.window_create(tk.END, window=star_btn)

        if is_dismissed:

            def _make_restore(u: str = url) -> None:
                self._restore_pr(u)

            btn = tk.Button(
                self._text,
                text="+",
                command=_make_restore,
                width=2,
                bg=BG_OUTPUT,
                fg=COLOR_DECLINED,
                font=self._font_body,
                relief=tk.FLAT,
                activebackground=COLOR_BUTTON_ACTIVE,
                cursor="hand2",
                padx=1,
                pady=0,
                borderwidth=0,
            )
        else:

            def _make_dismiss(u: str = url) -> None:
                self._dismiss_pr(u)

            btn = tk.Button(
                self._text,
                text="×",
                command=_make_dismiss,
                width=2,
                bg=BG_OUTPUT,
                fg=FG_DIM,
                font=self._font_body,
                relief=tk.FLAT,
                activebackground=COLOR_BUTTON_ACTIVE,
                cursor="hand2",
                padx=1,
                pady=0,
                borderwidth=0,
            )
        self._text.window_create(tk.END, window=btn)

        # Review PRs carry my change-request count, my PRs carry the
        # incoming one — never both, so they share a column.
        meta = self._review_meta.get(url)
        cr_count = meta[0] if meta is not None else self._incoming_cr_counts.get(url)
        cr_text = "" if cr_count is None else f"({cr_count})"
        cr_tag = "review_count" if cr_count else "review_zero"
        self._text.insert(tk.END, " " + cr_text.ljust(self._col_count), cr_tag)

        comment_count = pr.get("comments", 0)
        comment_tag = "review_count" if comment_count > 0 else "review_zero"
        self._text.insert(
            tk.END,
            " " + f"[{comment_count}]".ljust(self._col_comments),
            comment_tag,
        )

        stat = self._diffstat.get(url)
        if stat is not None:
            self._text.insert(tk.END, " (", "dim_mono")
            self._text.insert(tk.END, f"+{stat[0]}".rjust(self._col_add), "diff_add")
            self._text.insert(tk.END, "/", "dim_mono")
            self._text.insert(tk.END, f"-{stat[1]}".ljust(self._col_del), "diff_del")
            self._text.insert(tk.END, ")", "dim_mono")
        else:
            pad = self._col_add + self._col_del + 4
            self._text.insert(tk.END, " " * pad, "dim_mono")

        pr_text = f" {repo}  #{number} {title}"
        if draft:
            pr_text = f" {repo}  [draft] #{number} {title}"
        elif is_queued:
            pr_text = f" {repo}  [queued] #{number} {title}"
        link_tag = f"link_{id(pr)}"
        self._text.insert(tk.END, pr_text, link_tag)

        if is_dismissed:
            fg = COLOR_DECLINED
        elif draft or is_queued:
            fg = FG_DIM
        else:
            fg = COLOR_LINK
        self._text.tag_configure(link_tag, foreground=fg)

        def _open_pr(e: Any, u: str = url) -> None:
            webbrowser.open(u)

        self._text.tag_bind(link_tag, "<Button-1>", _open_pr)
        self._text.tag_bind(
            link_tag,
            "<Enter>",
            lambda e: self._text.configure(cursor="hand2"),
        )
        self._text.tag_bind(
            link_tag,
            "<Leave>",
            lambda e: self._text.configure(cursor="arrow"),
        )

        self._text.insert(tk.END, "\n")
        self._row_widgets[url] = btn

    def _dismiss_pr(self, url: str) -> None:
        self._dismissed.add(url)
        self._save_dismissed()
        self._render()

    def _restore_pr(self, url: str) -> None:
        self._dismissed.discard(url)
        self._save_dismissed()
        self._render()

    def _reset_dismissed(self) -> None:
        self._dismissed.clear()
        self._save_dismissed()
        self._render()

    def _load_dismissed(self) -> None:
        path = self._state_path / "dismissed_prs.json"
        if not path.exists():
            return
        try:
            with open(path) as f:
                self._dismissed = set(json.load(f))
        except (OSError, json.JSONDecodeError):
            pass

    def _save_dismissed(self) -> None:
        path = self._state_path / "dismissed_prs.json"
        try:
            atomic_write_json(path, sorted(self._dismissed))
        except OSError:
            pass

    def _save_cache(
        self,
        review_prs: list[dict[str, Any]],
        my_prs: list[dict[str, Any]],
        review_meta: dict[str, tuple[int, bool]],
        queued_urls: set[str],
        incoming_cr_counts: dict[str, int],
        requested_urls: set[str],
        diffstat: dict[str, tuple[int, int]],
    ) -> None:
        """Cache the last good fetch so a restart has something to show."""
        try:
            atomic_write_json(
                self._state_path / "prs_cache.json",
                {
                    "review_prs": review_prs,
                    "my_prs": my_prs,
                    "review_meta": {k: list(v) for k, v in review_meta.items()},
                    "queued_urls": sorted(queued_urls),
                    "incoming_cr_counts": incoming_cr_counts,
                    "requested_urls": sorted(requested_urls),
                    "diffstat": {k: list(v) for k, v in diffstat.items()},
                },
            )
        except (OSError, TypeError, ValueError):
            logger.warning("PR cache write failed", exc_info=True)

    def _load_cache(self) -> int | None:
        """Render the cached fetch. Returns its age in ms, None if unusable."""
        path = self._state_path / "prs_cache.json"
        try:
            age_s = time.time() - path.stat().st_mtime
            with open(path) as f:
                data = json.load(f)
            self._on_data_loaded(
                data["review_prs"],
                data["my_prs"],
                {k: (v[0], bool(v[1])) for k, v in data["review_meta"].items()},
                set(data["queued_urls"]),
                data["incoming_cr_counts"],
                set(data["requested_urls"]),
                {k: (v[0], v[1]) for k, v in data["diffstat"].items()},
            )
        except (OSError, json.JSONDecodeError, KeyError, TypeError, IndexError):
            return None
        # ponytail: clock skew or a future mtime reads as stale, which just
        # means a refresh now.
        return max(0, int(age_s * 1000))

    def _toggle_priority(self, url: str) -> None:
        if url in self._priority:
            self._priority.discard(url)
        else:
            self._priority.add(url)
        self._save_priority()
        self._render()

    def _load_priority(self) -> None:
        path = self._state_path / "priority_prs.json"
        if not path.exists():
            return
        try:
            with open(path) as f:
                self._priority = set(json.load(f))
        except (OSError, json.JSONDecodeError):
            pass

    def _save_priority(self) -> None:
        path = self._state_path / "priority_prs.json"
        try:
            atomic_write_json(path, sorted(self._priority))
        except OSError:
            pass

    def _update_label_star_btn(self) -> None:
        label = self._label_filter_var.get()
        if label == "All":
            self._label_star_btn.configure(text="\u2606", state=tk.DISABLED)
            return
        on = label in self._starred_labels
        self._label_star_btn.configure(
            text="\u2605" if on else "\u2606",
            fg=COLOR_NOTIFICATION_BELL if on else FG_DIM,
            state=tk.NORMAL,
        )

    def _toggle_label_star(self) -> None:
        label = self._label_filter_var.get()
        if label == "All":
            return
        if label in self._starred_labels:
            self._starred_labels.discard(label)
        else:
            self._starred_labels.add(label)
        self._save_starred_labels()
        self._update_label_star_btn()
        self._apply_label_stars()
        self._render()

    def _apply_label_stars(self) -> None:
        # ponytail: additive only. Un-starring a label leaves PR stars alone,
        # and a manually un-starred PR gets re-starred on the next refresh.
        urls = _label_starred_urls(
            self._review_prs + self._my_prs, self._starred_labels
        )
        if urls - self._priority:
            self._priority |= urls
            self._save_priority()

    def _load_starred_labels(self) -> None:
        path = self._state_path / "starred_labels.json"
        if not path.exists():
            return
        try:
            with open(path) as f:
                self._starred_labels = set(json.load(f))
        except (OSError, json.JSONDecodeError):
            pass

    def _save_starred_labels(self) -> None:
        path = self._state_path / "starred_labels.json"
        try:
            atomic_write_json(path, sorted(self._starred_labels))
        except OSError:
            pass
